text:
html[data-themed][data-appearance="vercel"] {
  --highlight-background: var(--color-workspace-theme-highlight-background-1);
  --highlight-foreground: var(--color-workspace-theme-highlight-foreground-2);
  --highlight-border: var(--color-workspace-theme-highlight-border-3);
  --progress-fill: var(--color-workspace-theme-highlight-foreground-2);
  --appearance-radius: 12px;
  --appearance-control-radius: 8px;
  --appearance-badge-radius: 6px;
  --background: var(--color-workspace-theme-background-4);
  --surface: var(--color-workspace-theme-surface-5);
  --card: var(--color-workspace-theme-card-6);
  --foreground: var(--color-workspace-theme-highlight-foreground-2);
  --muted-foreground: var(--color-workspace-theme-muted-foreground-7);
  --body: var(--muted-foreground);
  --border: var(--color-workspace-theme-border-8);
  --border-hover: var(--color-workspace-theme-border-hover-9);
  --control-border: var(--color-workspace-theme-control-border-10);
  --accent: var(--color-workspace-theme-highlight-foreground-2);
  --accent2: var(--color-workspace-theme-highlight-foreground-2);
  --accent-soft: var(--highlight-background);
  --primary: var(--accent);
  --primary-foreground: var(--color-workspace-theme-card-6);
  --on-accent: var(--color-workspace-theme-card-6);
  --muted: var(--surface);
  --link: var(--color-workspace-theme-highlight-foreground-2);
  --ring: var(--color-workspace-theme-highlight-foreground-2);
  --success: var(--color-workspace-theme-success-11);
  --queued: var(--color-workspace-theme-queued-12);
  --error: var(--color-workspace-theme-error-13);
  --status-success-text: var(--color-workspace-theme-success-11);
  --appearance-sent-bg: color-mix(in srgb, var(--success) 14%, var(--card));
  --status-warning-text: var(--color-workspace-theme-status-warning-text-14);
  --status-error-text: var(--color-workspace-theme-status-error-text-15);
  --destructive: var(--status-error-text);
  --warning: var(--status-warning-text);
  --warning-soft: var(--color-workspace-theme-warning-soft-16);
  --shadow: none;
  --button-foreground: var(--primary-action-ink);
  --button-gradient: var(--primary-action-gradient);
  --accent-gradient: var(--color-workspace-theme-highlight-foreground-2);
  --logo-background: var(--color-workspace-theme-highlight-foreground-2);
  --logo-ink: var(--color-workspace-theme-card-6);
  --avatar-background: var(--color-workspace-theme-highlight-background-1);
  --ring-track: var(--color-workspace-theme-border-8);
  --coral: var(--color-workspace-theme-coral-17);
  --placeholder-background: var(--highlight-background);
  --placeholder-foreground: var(--highlight-foreground);
  --skeleton-base: var(--color-workspace-theme-skeleton-base-18);
  --skeleton-highlight: var(--color-workspace-theme-surface-5);
  --scrollbar-thumb: var(--color-workspace-theme-scrollbar-thumb-19);
  --scrollbar-track: var(--background);
  --premium-notice-background: var(--surface);
  --premium-notice-border: var(--border);
  --premium-notice-text: var(--foreground);
  --recipients-bg: var(--background);
  --recipients-surface: var(--card);
  --recipients-card: var(--card);
  --recipients-border: var(--border);
  --recipients-text: var(--foreground);
  --recipients-text-muted: var(--body);
  --recipients-label: var(--body);
  --recipients-accent: var(--foreground);
  --recipients-accent-2: var(--foreground);
  --recipients-track: var(--border);
  --recipients-pill-bg: var(--color-workspace-theme-warning-soft-16);
  --recipients-pill-border: var(
    --color-workspace-theme-recipients-pill-border-20
  );
  --recipients-pill-text: var(--color-workspace-theme-status-warning-text-14);
  background: var(--background);
  color: var(--foreground);
  font-family: Arial, Helvetica, system-ui, sans-serif;

  --font-plus-jakarta: Arial, Helvetica, system-ui, sans-serif;
  --font-space-grotesk: Arial, Helvetica, system-ui, sans-serif;
  --appearance-primary: var(--foreground);
  --appearance-on-primary: var(--background);
  --appearance-border: var(--border-hover);
  --appearance-wash: var(--highlight-background);
  --appearance-link: var(--link);
  --appearance-focus: var(--ring);
  --appearance-shadow: none;
  --appearance-focus-shadow: 0 0 0 3px
    color-mix(in srgb, var(--ring) 18%, transparent);
  --appearance-card: var(--card);
  --appearance-decoration: none;
  --appearance-replied: var(--link);
  --appearance-replied-bg: color-mix(in srgb, var(--link) 12%, var(--card));
  --appearance-queued: var(--warning);
  --appearance-queued-bg: var(--warning-soft);
  --replied: var(--link);
  --status-replied-text: var(--link);
}

html[data-themed][data-appearance="vercel"][data-theme="dark"] {
  --highlight-background: var(--color-workspace-theme-highlight-background-21);
  --highlight-foreground: var(--color-workspace-theme-highlight-foreground-22);
  --highlight-border: var(--color-workspace-theme-highlight-border-23);
  --progress-fill: var(--color-workspace-theme-highlight-background-1);
  --background: var(--color-workspace-theme-background-24);
  --surface: var(--color-workspace-theme-surface-25);
  --card: var(--color-workspace-theme-card-26);
  --foreground: var(--color-workspace-theme-highlight-background-1);
  --muted-foreground: var(--color-workspace-theme-border-hover-9);
  --border: var(--color-workspace-theme-border-27);
  --border-hover: var(--color-workspace-theme-muted-foreground-7);
  --control-border: var(--color-workspace-theme-control-border-28);
  --accent: var(--color-workspace-theme-highlight-background-1);
  --accent2: var(--color-workspace-theme-highlight-background-1);
  --accent-soft: var(--highlight-background);
  --primary-foreground: var(--color-workspace-theme-highlight-foreground-2);
  --on-accent: var(--color-workspace-theme-highlight-foreground-2);
  --link: var(--color-workspace-theme-highlight-background-1);
  --ring: var(--color-workspace-theme-highlight-background-1);
  --success: var(--color-workspace-theme-success-29);
  --queued: var(--color-workspace-theme-queued-30);
  --error: var(--color-workspace-theme-error-31);
  --status-success-text: var(--color-workspace-theme-success-29);
  --status-warning-text: var(--color-workspace-theme-status-warning-text-32);
  --status-error-text: var(--color-workspace-theme-status-error-text-33);
  --warning-soft: var(--color-workspace-theme-warning-soft-34);
  --button-foreground: var(--primary-action-ink);
  --button-gradient: var(--primary-action-gradient);
  --accent-gradient: var(--color-workspace-theme-highlight-background-1);
  --logo-background: var(--color-workspace-theme-highlight-background-1);
  --logo-ink: var(--color-workspace-theme-highlight-foreground-2);
  --avatar-background: var(--color-workspace-theme-avatar-background-35);
  --ring-track: var(--color-workspace-theme-ring-track-36);
  --coral: var(--color-workspace-theme-coral-37);
  --placeholder-background: var(--highlight-background);
  --placeholder-foreground: var(--highlight-foreground);
  --skeleton-base: var(--color-workspace-theme-avatar-background-35);
  --skeleton-highlight: var(--color-workspace-theme-skeleton-highlight-38);
  --recipients-pill-bg: var(--color-workspace-theme-recipients-pill-bg-39);
  --recipients-pill-border: var(
    --color-workspace-theme-recipients-pill-border-40
  );
  --recipients-pill-text: var(--color-workspace-theme-status-warning-text-32);
}

html[data-workspace][data-appearance="vercel"] .page-container {
  max-width: 1240px;
}
html[data-workspace][data-appearance="vercel"] .workspace-screen-heading {
  margin: 16px 0 28px;
  padding-top: 0;
}
html[data-workspace][data-appearance="vercel"]
  .workspace-screen-heading
  > :is(p, div) {
  min-width: 0;
}
@media (max-width: 480px) {
  html[data-workspace][data-appearance="vercel"] .workspace-screen-heading {
    margin: 12px 0 24px;
  }
}
html[data-workspace][data-appearance="vercel"] {
  --nav-active-bg: var(--highlight-background);
  --nav-active-line: var(--highlight-border);
  --nav-active-ink: var(--foreground);
  --nav-muted: var(--body);
  --nav-hover: var(--surface);
}
html[data-workspace][data-appearance="vercel"] .workspace-header-controls {
  --workspace-track: var(--surface);
  background: transparent;
  border-color: var(--border);
  box-shadow: none;
}
html[data-workspace][data-appearance="vercel"] .theme-track {
  background: var(--surface);
  border-color: var(--border);
}
html[data-workspace][data-appearance="vercel"] .theme-thumb {
  background: var(--foreground);
  color: var(--background);
  box-shadow: none;
}
html[data-workspace][data-appearance="vercel"] .workspace-avatar {
  color: var(--foreground);
  border: 1px solid var(--border);
}
html[data-workspace][data-appearance="vercel"]
  :is(.workspace-account-menu, .logo-mark) {
  border-radius: var(--appearance-control-radius);
  box-shadow: none;
}

html[data-workspace][data-appearance="vercel"] .compose-page .compose-hero {
  display: block;
  margin: 16px 0 28px;
}
@media (max-width: 480px) {
  html[data-workspace][data-appearance="vercel"] .compose-page .compose-hero {
    margin: 12px 0 24px;
  }
}
html[data-workspace][data-appearance="vercel"] .compose-page .compose-hero h1 {
  font-size: 30px;
  line-height: 1.25;
  letter-spacing: -1px;
  font-weight: 650;
}
html[data-workspace][data-appearance="vercel"] .compose-page .compose-hero p {
  margin-top: 7px;
  color: var(--body);
  font-size: 14px;
}
html[data-workspace][data-appearance="vercel"] .compose-page .compose-grid {
  grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr);
  gap: 24px;
}
html[data-workspace][data-appearance="vercel"] .compose-page .compose-grid > * {
  min-width: 0;
}
html[data-workspace][data-appearance="vercel"] .compose-page .compose-search {
  margin-bottom: 24px;
}
html[data-workspace][data-appearance="vercel"]
  .compose-page
  :is(
    select,
    input:not([type="checkbox"]),
    textarea,
    [data-slot="button"],
    .role-chip
  ) {
  border-radius: var(--appearance-control-radius);
}
html[data-workspace][data-appearance="vercel"] .compose-page .panel {
  padding: 22px;
  background: var(--card);
  box-shadow: none;
}
html[data-workspace][data-appearance="vercel"]
  .compose-page
  :is(.eyebrow, .section-label),
html[data-workspace][data-appearance="vercel"]
  .compose-page
  .recipient-panel
  .eyebrow,
html[data-workspace][data-appearance="vercel"]
  .compose-page
  .send-queue-panel
  > .section-label {
  color: var(--coral);
  font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
html[data-workspace][data-appearance="vercel"]
  .compose-page
  :is(select, input:not([type="checkbox"]), textarea) {
  background: var(--card);
}
html[data-workspace][data-appearance="vercel"]
  .compose-page
  input[type="checkbox"] {
  accent-color: var(--foreground);
}
html[data-workspace][data-appearance="vercel"] .compose-page .mail-preview {
  background: var(--background);
  border: 1px solid var(--border);
}
html[data-workspace][data-appearance="vercel"] .compose-page .recipient-card {
  padding: 16px;
  border: 1px solid var(--border);
  border-radius: var(--appearance-radius);
  background: var(--background);
  gap: 8px;
}
html[data-workspace][data-appearance="vercel"]
  .compose-page
  .recipient-card:has(input:checked) {
  border-top-color: var(--border-hover);
}
html[data-workspace][data-appearance="vercel"]
  .compose-page
  .recipient-header
  .text-\[17px\] {
  font-size: 15px;
}
html[data-workspace][data-appearance="vercel"]
  .compose-page
  .recipient-details {
  font-size: 12px;
  row-gap: 6px;
}
html[data-workspace][data-appearance="vercel"]
  .compose-page
  .recipient-card-emailed {
  border-left: 2px solid var(--recipients-pill-border);
  padding-left: 12px;
}
html[data-workspace][data-appearance="vercel"]
  .compose-page
  .recipient-warning {
  border-radius: var(--appearance-badge-radius);
}
html[data-workspace][data-appearance="vercel"]
  .compose-page
  .recipient-meter-track,
html[data-workspace][data-appearance="vercel"]
  .compose-page
  .recipient-meter-fill {
  border-radius: 3px;
}
html[data-workspace][data-appearance="vercel"]
  .compose-page
  .recipient-meter-fill {
  background: var(--progress-fill);
}
html[data-workspace][data-appearance="vercel"] .compose-page .send-checklist {
  --checklist-background: var(--background);
  --checklist-ring: var(--border-hover);
  --checklist-ok: var(--success);
  border: 1px solid var(--border);
  border-radius: var(--appearance-radius);
  padding: 16px;
  gap: 12px;
}
html[data-workspace][data-appearance="vercel"]
  .compose-page
  .send-checklist
  h3 {
  font-size: 14px;
}
html[data-workspace][data-appearance="vercel"]
  .compose-page
  .send-checklist-copy {
  font-size: 13px;
}
html[data-workspace][data-appearance="vercel"]
  .compose-page
  .send-checklist-glow {
  display: none;
}
html[data-workspace][data-appearance="vercel"]
  .compose-page
  .send-queue-panel
  > [aria-live="polite"]:empty {
  min-height: 0;
  margin-block: 0;
}
html[data-workspace][data-appearance="vercel"] .compose-page .progress-ring {
  font-family: Arial, Helvetica, system-ui, sans-serif;
}
html[data-workspace][data-appearance="vercel"] .compose-page .progress-arc {
  filter: none;
}
html[data-workspace][data-appearance="vercel"] .compose-page dialog {
  border-radius: var(--appearance-radius);
  box-shadow: 0 16px 64px var(--color-workspace-theme-box-shadow-41);
}
html[data-workspace][data-appearance="vercel"] .compose-page dialog::backdrop {
  background: var(--color-workspace-theme-background-42);
}
html[data-workspace][data-appearance="vercel"] .primary-button:disabled {
  background: var(--surface);
  color: var(--body);
  opacity: 1;
  box-shadow: none;
}
html[data-workspace][data-appearance="vercel"] .button-interaction {
  border-radius: var(--appearance-control-radius);
}
html[data-workspace][data-appearance="vercel"] [role="tooltip"] {
  background: var(--card);
  border-color: var(--border);
  color: var(--foreground);
  border-radius: var(--appearance-control-radius);
  box-shadow: 0 4px 16px var(--color-workspace-theme-box-shadow-43);
}
html[data-workspace][data-appearance="vercel"]
  .compose-page
  .skeleton:not(.workspace-nav-placeholder) {
  border-radius: var(--appearance-control-radius);
}

@media (max-width: 1023px) {
  html[data-workspace][data-appearance="vercel"] .compose-page .compose-grid {
    gap: 18px;
  }
  html[data-workspace][data-appearance="vercel"] .compose-page .panel {
    padding: 18px;
  }
}
@media (max-width: 767px) {
  html[data-workspace][data-appearance="vercel"] .compose-page .compose-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  html[data-workspace][data-appearance="vercel"]
    .compose-page
    .compose-hero
    h1 {
    font-size: 28px;
  }
  html[data-workspace][data-appearance="vercel"] .compose-page .panel {
    padding: 16px;
  }
  html[data-workspace][data-appearance="vercel"]
    .compose-page
    .send-queue-panel
    > .flex:has([aria-label="Sending capacity"]) {
    flex-wrap: wrap;
  }
}
@media (forced-colors: active) {
  html[data-workspace][data-appearance="vercel"]
    .compose-page
    .recipient-meter-fill {
    background: Highlight;
  }
}

html[data-workspace][data-appearance="vercel"] .compose-page .chip {
  border-style: solid;
  border-radius: var(--appearance-control-radius);
  color: var(--foreground);
  font-family: inherit;
}
html[data-workspace][data-appearance="vercel"] .compose-page .font-num {
  font-family: inherit;
}
html[data-workspace][data-appearance="vercel"] .workspace-header-controls {
  border-radius: var(--appearance-radius);
}
html[data-workspace][data-appearance="vercel"] .theme-track {
  border-radius: var(--appearance-control-radius);
}
html[data-workspace][data-appearance="vercel"] .theme-thumb {
  border-radius: var(--appearance-badge-radius);
}
html[data-workspace][data-appearance="vercel"]
  .compose-page
  :is(.panel, .mail-preview, .recipient-card, .send-checklist):hover {
  transform: none !important;
  box-shadow: none !important;
}
html[data-workspace][data-appearance="vercel"] .compose-page dialog[open] {
  border-radius: var(--appearance-radius);
}

html[data-workspace][data-appearance="vercel"]
  :is(.workspace-gmail, .workspace-account-trigger) {
  border-radius: var(--appearance-control-radius);
}
html[data-workspace][data-appearance="vercel"] .compose-page textarea {
  font-family: inherit;
}
html[data-workspace][data-appearance="vercel"] .compose-page dialog {
  border-color: var(--border);
}

html[data-workspace][data-appearance="vercel"]
  :is(button, [role="button"], .button-interaction) {
  --button-hover-filter: drop-shadow(
    0 2px 6px
      color-mix(in srgb, var(--button-interaction-color) 12%, transparent)
  );
}

html[data-workspace][data-appearance="vercel"]
  .compose-page
  .recipient-summary {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  min-width: 0;
}
html[data-workspace][data-appearance="vercel"] .compose-page .recipient-email {
  display: block;
  margin-top: 3px;
  color: var(--body);
  font-size: 13px;
  overflow-wrap: anywhere;
}
html[data-workspace][data-appearance="vercel"]
  .compose-page
  .recipient-role-badge {
  max-width: 180px;
  padding: 5px 10px;
  border-radius: var(--appearance-badge-radius);
  border: 1px solid var(--highlight-border);
  background: var(--highlight-background);
  color: var(--highlight-foreground);
  font-size: 12px;
  font-weight: 500;
  overflow-wrap: anywhere;
}
@media (max-width: 600px) {
  html[data-workspace][data-appearance="vercel"]
    .compose-page
    .recipient-summary {
    grid-template-columns: 18px minmax(0, 1fr);
    gap: 8px 12px;
  }
  html[data-workspace][data-appearance="vercel"]
    .compose-page
    .recipient-role-badge {
    grid-column: 2;
    justify-self: start;
    max-width: 100%;
  }
}

/* Vercel is opt-in and active only on workspace paths. Tokens live on html so
   native dialogs, portaled content, and retained route trees share one palette. */
html[data-workspace][data-appearance="vercel"] body {
  background: var(--background);
  color: var(--foreground);
}
html[data-workspace][data-appearance="vercel"] body > header {
  background: var(--card);
  border-bottom: 1px solid var(--border);
}
html[data-workspace][data-appearance="vercel"]
  :is(.panel, .mail-preview, dialog) {
  border-radius: var(--appearance-radius);
  background: var(--card);
  box-shadow: none;
  border-color: var(--border);
}
/* Use the same geometry for the main actions on every workspace page. */
html[data-workspace][data-appearance="vercel"]
  .button-interaction:is(
    .primary-button,
    .primary-action,
    .secondary-button,
    .ghost-button
  ):not(.upgrade-shine) {
  min-height: 44px;
  padding: 10px 16px;
  border-radius: var(--appearance-control-radius);
  font-size: 13px;
  line-height: 1.35;
  font-weight: 600;
  box-shadow: none;
}
html[data-workspace][data-appearance="vercel"]
  .button-interaction:is(.secondary-button, .ghost-button):not(.upgrade-shine) {
  border: 1px solid var(--control-border);
}
html[data-workspace][data-appearance="vercel"]
  .button-interaction.ghost-button:not(.upgrade-shine) {
  border-color: transparent;
}
html[data-workspace][data-appearance="vercel"]
  .button-interaction:is(
    :disabled,
    [aria-disabled="true"],
    [aria-busy="true"]
  ) {
  cursor: not-allowed;
  box-shadow: none;
  filter: none;
}
html[data-workspace][data-appearance="vercel"]
  :is(select, textarea, [data-slot="input"], [data-slot="button"]) {
  border-radius: var(--appearance-control-radius);
}
html[data-workspace][data-appearance="vercel"] :is(.eyebrow, .section-label) {
  color: var(--coral);
}
html[data-workspace][data-appearance="vercel"]
  :is(
    .hover-card:not(.campaign-progress-stat),
    .recipient-card,
    .send-checklist
  ):hover {
  transform: none !important;
  box-shadow: none !important;
}
html[data-workspace][data-appearance="vercel"] dialog::backdrop {
  background: var(--color-workspace-theme-background-42);
}
html[data-workspace][data-appearance="vercel"]
  .skeleton:not(.workspace-nav-placeholder) {
  border-radius: var(--appearance-control-radius);
}
html[data-workspace][data-appearance="vercel"] .progress-arc {
  filter: none;
}
html[data-workspace][data-appearance="vercel"] .appearance-trigger {
  border-radius: var(--appearance-control-radius);
}
html[data-workspace][data-appearance="vercel"]
  :is(
    .free-template-overview,
    .free-retained-templates,
    .paid-template-library
  ) {
  --body: var(--muted-foreground);
}
html[data-workspace][data-appearance="vercel"]
  :is(.paid-template-library, .free-template-card, .free-retained-card) {
  border-radius: var(--appearance-radius);
}
html[data-workspace][data-appearance="vercel"]
  :is(.success-confirmation, .success-toast) {
  border-radius: var(--appearance-radius);
}
html[data-workspace][data-appearance="vercel"] .status-replied {
  color: var(--link);
  background: color-mix(in srgb, var(--link) 12%, var(--card));
  box-shadow: none;
}

/* Shared controls include module-backed and portaled actions. Keep avatars,
   status dots, checkboxes, and compact help icons circular. */
html[data-workspace][data-appearance="vercel"]
  :is(
    button,
    [role="button"],
    [role="menuitem"],
    [role="menuitemradio"],
    input:where(:not([type="checkbox"]):not([type="radio"])),
    select,
    textarea,
    .button-interaction,
    .role-chip,
    .chip,
    :where(.workspace-account-menu a),
    :where(.pagination a),
    .tutorial-mini-primary
  ) {
  border-radius: var(--appearance-control-radius);
}
html[data-workspace][data-appearance="vercel"]
  :is(
    .help-button,
    .help-dismiss,
    .tutorial-dot-slot,
    .workspace-avatar,
    button.plan-info-icon,
    button:has(> .info-icon)
  ) {
  border-radius: 50%;
}
html[data-workspace][data-appearance="vercel"]
  :is(button, input, select, textarea):disabled,
html[data-workspace][data-appearance="vercel"] [aria-disabled="true"] {
  opacity: 1;
  background: var(--surface);
  color: var(--body);
  border-color: var(--control-border);
  box-shadow: none;
  filter: none;
}
html[data-workspace][data-appearance="vercel"]
  :is(button, a, [tabindex]):focus-visible:not(
    :where(input, select, textarea)
  ) {
  outline: 2px solid var(--ring);
  outline-offset: 3px;
}
html[data-workspace][data-appearance="vercel"]
  :is(button, .button-interaction):hover:not(:disabled) {
  --button-hover-filter: none;
  translate: none;
}
html[data-workspace][data-appearance="vercel"]
  :is([aria-pressed="true"], [aria-checked="true"]):not(:disabled) {
  border-color: var(--highlight-border);
  background: var(--highlight-background);
  color: var(--highlight-foreground);
}
html[data-workspace][data-appearance="vercel"]
  :is(.status-badge, .free-template-selected, .recipient-warning) {
  border-radius: var(--appearance-badge-radius);
}
/* Preview personalization and the selected-recipient ring stay yellow. */
html[data-workspace][data-appearance="vercel"] .compose-page {
  --placeholder-background: var(--color-workspace-theme-queued-30);
  --placeholder-foreground: var(--color-workspace-theme-highlight-foreground-2);
}
html[data-workspace][data-appearance="vercel"] .help-button {
  background: var(--primary);
  color: var(--primary-foreground);
  border-color: var(--control-border);
  box-shadow: 0 2px 8px var(--color-workspace-theme-box-shadow-43);
}
html[data-workspace][data-appearance="vercel"] .help-button:hover {
  background: color-mix(in srgb, var(--primary) 85%, var(--card));
  animation: none;
}
html[data-workspace][data-appearance="vercel"] .help-button::after {
  display: none;
}
html[data-workspace][data-appearance="vercel"] .help-dismiss {
  background: var(--card);
  color: var(--foreground);
  box-shadow: none;
}
html[data-workspace][data-appearance="vercel"]
  :is(.help-cloud, .tutorial-hint) {
  border-radius: var(--appearance-radius);
  border: 1px solid var(--highlight-border);
  background: var(--highlight-background);
  color: var(--highlight-foreground);
}
html[data-workspace][data-appearance="vercel"]
  :is(.help-cloud::before, .help-cloud::after) {
  border-color: var(--highlight-border);
  background: var(--highlight-background);
}
html[data-workspace][data-appearance="vercel"] dialog.tutorial-dialog {
  border-radius: 0;
  background: transparent;
}
html[data-workspace][data-appearance="vercel"] .tutorial-card {
  border-radius: var(--appearance-radius);
  box-shadow: 0 16px 64px var(--color-workspace-theme-box-shadow-41);
}
html[data-workspace][data-appearance="vercel"]
  :is(.help-dismiss, .tutorial-arrow, .tutorial-close):hover:not(:disabled) {
  background: var(--surface);
  color: var(--foreground);
}
html[data-workspace][data-appearance="vercel"]
  :is(
    .tutorial-progress > span,
    .tutorial-dot-slot > span.is-active,
    .tutorial-dot-slot > span::after
  ) {
  background: var(--progress-fill);
}
html[data-workspace][data-appearance="vercel"] .tutorial-mini-primary {
  background: var(--primary);
  color: var(--primary-foreground);
}

html[data-workspace][data-appearance="vercel"]
  .compose-page
  :is(.panel, .mail-preview, .recipient-card) {
  border-radius: var(--appearance-radius);
}
html[data-workspace][data-appearance="vercel"]
  .appearance-menu
  button[aria-checked="true"] {
  background: var(--highlight-background);
  color: var(--highlight-foreground);
}

/* Feature tiles are deliberately separate from selected fields and links. */
html[data-workspace][data-appearance="vercel"] {
  --workspace-icon-bg: var(--color-workspace-theme-highlight-background-1);
  --workspace-icon-ink: var(--color-workspace-theme-highlight-foreground-2);
  --workspace-icon-border: var(--color-workspace-theme-control-border-10);
}
html[data-workspace][data-appearance="vercel"] .workspace-icon-tile {
  background: var(
    --workspace-icon-bg,
    var(--color-workspace-theme-highlight-background-1)
  );
  color: var(
    --workspace-icon-ink,
    var(--color-workspace-theme-highlight-foreground-2)
  );
  box-shadow: inset 0 0 0 1px
    var(--workspace-icon-border, var(--color-workspace-theme-control-border-10));
}
html[data-workspace][data-appearance="vercel"] .workspace-icon-glyph {
  color: var(--foreground);
}
html[data-workspace][data-appearance="vercel"][data-theme="dark"] {
  --workspace-icon-bg: var(--color-workspace-theme-highlight-background-21);
  --workspace-icon-ink: var(--color-workspace-theme-highlight-foreground-22);
  --workspace-icon-border: var(
    --color-workspace-theme-workspace-icon-border-44
  );
}

/* History and its portals own their neutral highlights, independently of the
   neutral selections used on Compose, Templates, and Contacts. */
html[data-workspace][data-appearance="vercel"]
  :is(.history-page, .history-surface) {
  --highlight-background: var(--color-workspace-theme-highlight-background-1);
  --highlight-foreground: var(--color-workspace-theme-highlight-foreground-2);
  --highlight-border: var(--color-workspace-theme-control-border-10);
  --history-role-text: var(--color-workspace-theme-highlight-foreground-2);
  --history-role-background: var(
    --color-workspace-theme-highlight-background-1
  );
  --history-role-border: var(--color-workspace-theme-highlight-border-3);
  --link: var(--foreground);
  --ring: var(--foreground);
  --progress-fill: var(--foreground);
  --appearance-link: var(--foreground);
  --appearance-focus: var(--foreground);
  --appearance-border: var(--border-hover);
  --appearance-wash: var(--highlight-background);
  --appearance-replied: var(--foreground);
  --appearance-replied-bg: var(--surface);
  --appearance-focus-shadow: none;
  --tooltip-pink: var(--foreground);
}
html[data-workspace][data-appearance="vercel"][data-theme="dark"]
  :is(.history-page, .history-surface) {
  --highlight-background: var(--color-workspace-theme-highlight-background-21);
  --highlight-foreground: var(--color-workspace-theme-highlight-foreground-22);
  --highlight-border: var(--color-workspace-theme-workspace-icon-border-44);
  --history-role-text: var(--color-workspace-theme-highlight-foreground-22);
  --history-role-background: var(
    --color-workspace-theme-highlight-background-21
  );
  --history-role-border: var(--color-workspace-theme-highlight-border-23);
}
html[data-workspace][data-appearance="vercel"]
  :is(.history-page, .history-surface)
  :is(button, a, [tabindex]):focus-visible:not(
    :where(input, select, textarea)
  ) {
  outline-color: var(--foreground);
}
html[data-workspace][data-appearance="vercel"]
  :is(.history-page, .history-surface)
  :is(button, [role="button"], .button-interaction) {
  --button-hover-filter: none;
}
html[data-workspace][data-appearance="vercel"] .history-surface {
  --tooltip-pink: var(--foreground);
}

/* Shared help surfaces, including the miniature examples inside the dialog. */
html[data-workspace][data-appearance="vercel"]
  :is(.help-launcher, .tutorial-dialog) {
  --highlight-background: var(--surface);
  --highlight-foreground: var(--foreground);
  --highlight-border: var(--border);
  --accent-soft: var(--surface);
  --link: var(--foreground);
  --ring: var(--foreground);
  --progress-fill: var(--foreground);
  --placeholder-background: var(--surface);
  --placeholder-foreground: var(--foreground);
}
html[data-workspace][data-appearance="vercel"]
  :is(.tutorial-card, .tutorial-hint) {
  border-radius: var(--appearance-radius);
}
html[data-workspace][data-appearance="vercel"]
  :is(.help-cloud, .help-cloud::before, .help-cloud::after) {
  background: var(--card);
  color: var(--foreground);
  border-color: var(--border);
}
/* On narrow screens the help launcher follows the workspace footer, leaving
   the Compose controls and send action unobstructed. */
@media (max-width: 480px) {
  html[data-workspace][data-appearance="vercel"] .help-launcher {
    position: relative;
    right: auto;
    bottom: auto;
    margin: 0 max(20px, env(safe-area-inset-right)) 24px auto;
  }
  html[data-workspace][data-appearance="vercel"]
    body:has(.help-launcher)
    footer.page-container {
    padding-bottom: 32px;
  }
}
html[data-workspace][data-appearance="vercel"] .tutorial-hint {
  background: var(--surface);
  color: var(--foreground);
  border-color: var(--border);
}
html[data-workspace][data-appearance="vercel"] .tutorial-progress {
  background: var(--border);
}
html[data-workspace][data-appearance="vercel"] .tutorial-mini-check {
  color: var(--primary-foreground);
}
html[data-workspace][data-appearance="vercel"] .tutorial-mini-ring {
  background: var(--border);
  box-shadow: inset 0 0 0 7px var(--status-success-text);
}
html[data-workspace][data-appearance="vercel"] .tutorial-mini-ring.is-draft {
  box-shadow: inset 0 0 0 7px var(--status-warning-text);
}
html[data-workspace][data-appearance="vercel"]
  .tutorial-dialog
  :is(button, .button-interaction) {
  --button-hover-filter: none;
}

/* Semantic colors also cover the shared connection dot and older status pills. */
html[data-workspace][data-appearance="vercel"]
  .workspace-gmail[data-connected="true"]
  .workspace-gmail-dot {
  background: var(--success);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--success) 18%, transparent);
}
html[data-workspace][data-appearance="vercel"]
  .workspace-gmail[data-connected="false"]
  .workspace-gmail-dot {
  background: var(--queued);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--queued) 18%, transparent);
}
html[data-workspace][data-appearance="vercel"] .status-sent {
  color: var(--status-success-text);
  background: color-mix(in srgb, var(--success) 14%, var(--card));
  box-shadow: inset 0 0 0 1px
    color-mix(in srgb, var(--success) 28%, transparent);
}

/* Clearer semantic accents on Vercel's light queue and connection indicator. */
html[data-workspace][data-appearance="vercel"][data-theme="light"]
  .send-queue-panel {
  --success: var(--color-workspace-theme-success-45);
  --queued: var(--color-workspace-theme-queued-46);
}
html[data-workspace][data-appearance="vercel"][data-theme="light"]
  .workspace-gmail[data-connected="true"]
  .workspace-gmail-dot {
  background: var(--color-workspace-theme-success-45);
  box-shadow: 0 0 0 4px var(--color-workspace-theme-box-shadow-47);
}

/* Selected history filters need a visible boundary as well as a neutral wash. */
html[data-workspace][data-appearance="vercel"]
  :is(.history-page, .history-surface) {
  --highlight-border: var(--input-boundary);
}
